/**
 * One layer of an icon: an SVG path (24x24 viewBox) pre-flattened at build time into commands
 * (0 = moveTo x y, 1 = lineTo x y, 2 = cubicTo x1 y1 x2 y2 x y, 3 = close), and how to paint it.
 */
class IconLayer(val kind: Int, val cmds: FloatArray) {
    fun toPath(): android.graphics.Path {
        val p = android.graphics.Path()
        var i = 0
        while (i < cmds.size) {
            when (cmds[i].toInt()) {
                0 -> { p.moveTo(cmds[i + 1], cmds[i + 2]); i += 3 }
                1 -> { p.lineTo(cmds[i + 1], cmds[i + 2]); i += 3 }
                2 -> { p.cubicTo(cmds[i + 1], cmds[i + 2], cmds[i + 3], cmds[i + 4], cmds[i + 5], cmds[i + 6]); i += 7 }
                else -> { p.close(); i += 1 }
            }
        }
        return p
    }
}

